# langs/brainfuck.py
from core.base import Language
from core.helpers import bf_print_string


# --- PATCH: non-blocking stdin ---
import sys as _sys_patch

def run_brainfuck_io(src):
    """Brainfuck с поддержкой ввода через input(), только в TTY.

    В неинтерактивном режиме (тесты, Executor) `,` даёт 0 и не блокирует
    процесс на чтении stdin.
    """
    bf = "".join(c for c in src if c in '><+-.,[]')
    tape = [0] * 30000
    ptr = 0
    out = []
    br = {}
    st = []
    for i, c in enumerate(bf):
        if c == '[':
            st.append(i)
        elif c == ']' and st:
            j = st.pop()
            br[i] = j
            br[j] = i
    pc = 0
    steps = 0
    limit = 50_000_000
    while pc < len(bf) and steps < limit:
        steps += 1
        c = bf[pc]
        if c == '>':
            ptr = (ptr + 1) % 30000
        elif c == '<':
            ptr = (ptr - 1) % 30000
        elif c == '+':
            tape[ptr] = (tape[ptr] + 1) & 0xFF
        elif c == '-':
            tape[ptr] = (tape[ptr] - 1) & 0xFF
        elif c == '.':
            out.append(chr(tape[ptr]))
        elif c == ',':
            try:
                if _sys_patch.stdin.isatty():
                    line = input()
                    tape[ptr] = ord(line[0]) & 0xFF if line else 0
                else:
                    tape[ptr] = 0
            except BaseException:
                tape[ptr] = 0
        elif c == '[':
            if tape[ptr] == 0:
                pc = br.get(pc, pc)
        elif c == ']':
            if tape[ptr] != 0:
                pc = br.get(pc, pc)
        pc += 1
    return "".join(out)
# --- /PATCH ---

from core.translate import TRANSPILERS


# ==================================================================
#  Brainfuck → Python (на уровне модуля, чтобы ook.py мог импортировать)
# ==================================================================
def _bf_to_python(src):
    """Превращает BF-программу в линейный Python-код с while-циклами."""
    bf = "".join(c for c in src if c in '><+-.,[]')
    lines = ["_t = [0] * 30000", "_p = 0", "_out = []"]
    ind = 0

    for c in bf:
        pad = "    " * ind
        if c == '>':
            lines.append(pad + "_p = (_p + 1) % 30000")
        elif c == '<':
            lines.append(pad + "_p = (_p - 1) % 30000")
        elif c == '+':
            lines.append(pad + "_t[_p] = (_t[_p] + 1) & 0xFF")
        elif c == '-':
            lines.append(pad + "_t[_p] = (_t[_p] - 1) & 0xFF")
        elif c == '.':
            lines.append(pad + "_out.append(chr(_t[_p]))")
        elif c == '[':
            lines.append(pad + "while _t[_p] != 0:")
            ind += 1
        elif c == ']':
            ind = max(0, ind - 1)

    lines.append("print(''.join(_out), end='')")
    return "\n".join(lines) + "\n"


